{
  "name": "skillz.sh",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "bun run build.ts",
    "build:clean": "bun run build.ts --clean",
    "build:publish": "bun run build.ts && bun run publish.ts",
    "build:docs": "cd docs && npm run build",
    "build:all": "bun run build.ts && npm run build:docs",
    "serve": "bun scripts/serve.ts",
    "watch": "bun run --watch build.ts"
  },
  "devDependencies": {
    "@linear/sdk": "^29.0.0",
    "playwright": "^1.57.0",
    "@types/bun": "latest"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "mcp": {
    "context7": {
      "type": "remote",
      "url": "https://mcp.context7.com/mcp"
    },
    "grep_app": {
      "type": "remote",
      "url": "https://mcp.grep.app"
    },
    "playwriter": {
      "type": "local",
      "command": ["npx", "playwriter@latest"],
      "enabled": false
    }
  }
}

{
  "name": "@bind/skillz",
  "version": "0.0.6",
  "description": "CLI for distributing OpenCode skills",
  "type": "module",
  "bin": {
    "skillz": "./src/cli.ts",
    "skz": "./src/cli.ts"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "dev": "bun run ./src/cli.ts",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "skills",
    "cli",
    "ai",
    "agents"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Bind/skillz.sh.git",
    "directory": "cli"
  },
  "author": "Doug Binder",
  "license": "MIT",
  "dependencies": {
    "@inquirer/prompts": "^7.0.0",
    "@opentui/core": "^0.1.67",
    "yaml": "^2.8.2"
  },
  "devDependencies": {
    "@types/bun": "latest"
  },
  "peerDependencies": {
    "typescript": "^5"
  }
}

{
  "name": "linear-cli",
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "list-issues": "bun run list-issues.ts",
    "get-issue": "bun run get-issue.ts",
    "create-issue": "bun run create-issue.ts",
    "update-issue": "bun run update-issue.ts"
  },
  "dependencies": {
    "@linear/sdk": "^29.0.0"
  }
}

